function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
const st = $('Read STARTUPS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
if (trk.length < 200) { throw new Error('ABORT: tracker only ' + trk.length + ' rows - truncated'); }

// contactable investor book
const live = [];
for (const r of inv) {
  const n = s(r.investor);
  if (!n) { continue; }
  if (s(r.do_not_contact).toLowerCase() === 'yes') { continue; }
  live.push(n);
}
const liveKeys = {};
for (const n of live) { liveKeys[nz(n)] = 1; }
const liveCount = Object.keys(liveKeys).length;

// active startups
const active = [];
for (const r of st) {
  const n = s(r.startup);
  if (!n) { continue; }
  if (s(r.active).toLowerCase() !== 'yes') { continue; }
  active.push({ name: n, owner: s(r.owner) });
}

// tracker: investor -> set of startup names mentioned in the deal columns
const cols = Object.keys(trk[0] || {});
let cInv = null; const cDeals = [];
for (const c of cols) {
  const l = c.toLowerCase();
  if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; }
  if (l.indexOf('deals shared') >= 0 || l.indexOf('latest deal') >= 0 || l.indexOf('picked') >= 0) { cDeals.push(c); }
}
const trkText = [];
for (const r of trk) {
  const iv = nz(r[cInv]);
  if (!iv) { continue; }
  let blob = '';
  for (const c of cDeals) { blob += ' ' + s(r[c]); }
  trkText.push({ inv: iv, blob: nz(blob) });
}

const today = new Date('2026-09-09T00:00:00Z');
function parseDate(v) {
  const t = s(v);
  if (!t) { return null; }
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) { return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])); }
  m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  if (m) { return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1])); }
  const d = new Date(t);
  return isNaN(d.getTime()) ? null : d;
}

// group pipeline by startup
const byStartup = {};
for (const p of pipe) {
  const k = nz(p.startup);
  if (!k) { continue; }
  if (!byStartup[k]) { byStartup[k] = []; }
  byStartup[k].push(p);
}

const rows = [];
for (const a of active) {
  const k = nz(a.name);
  const mine = byStartup[k] || [];
  let sent = 0, passed = 0, queued = 0, paused = 0, replied = 0, sent30 = 0;
  const pairedKeys = {};
  for (const p of mine) {
    const iv = nz(p.investor);
    if (iv) { pairedKeys[iv] = 1; }
    const isPaused = s(p.pause).toLowerCase() === 'yes';
    const isSent = s(p.deal_shared).toLowerCase() === 'yes';
    if (isSent) {
      sent++;
      const r = s(p.investor_response).toLowerCase();
      if (r) { replied++; }
      if (r === 'pass' || r === 'passed') { passed++; }
      const d = parseDate(p.date_shared);
      if (d && (today - d) / 86400000 <= 30) { sent30++; }
    } else if (isPaused) { paused++; }
    else { queued++; }
  }
  // tracker pairs count against headroom too
  for (const t of trkText) {
    if (t.blob.indexOf(k) >= 0 && k.length > 3) { pairedKeys[t.inv] = 1; }
  }
  let unpaired = 0;
  for (const key of Object.keys(liveKeys)) { if (!pairedKeys[key]) { unpaired++; } }

  // pace from the trailing 30 days, expressed per weekday (~22 weekdays)
  const perWeekday = sent30 / 22;
  const runwayWeekdays = perWeekday > 0 ? Math.round(queued / perWeekday) : null;
  rows.push({ startup: a.name, owner: a.owner, queued: queued, sent: sent, passed: passed,
    replied: replied, paused: paused, sent_last_30d: sent30,
    pace_per_weekday: Math.round(perWeekday * 100) / 100,
    runway_weekdays: runwayWeekdays, unpaired_headroom: unpaired });
}
rows.sort(function (a, b) { return a.queued - b.queued || a.startup.localeCompare(b.startup); });
return [{ json: { generated: '2026-09-09', live_investors: liveCount, active_startups: rows.length,
  tracker_rows: trk.length, pipeline_rows: pipe.length, rows: rows } }];
